    /** Logos whose paths draw counters as overlapping shapes (need even-odd to punch through). */
    private val evenOddLogos = emptySet<String>()

    private val cache = HashMap<String, ImageVector>()

    /** The mark for [platformId], or null (callers fall back to a generic icon). */
    fun forPlatform(platformId: String): ImageVector? = byPlatform[platformId]?.let(::named)

    /** True when [platformId] shows a real brand logo (not an outline). */
    fun isLogo(platformId: String): Boolean = byPlatform[platformId] in logos

    fun named(name: String): ImageVector? = synchronized(cache) {
        cache[name] ?: (logos[name] ?: outlines[name])?.let { d ->
            ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).addPath(addPathNodes(d), pathFillType = if (name in logos && name !in evenOddLogos) PathFillType.NonZero else PathFillType.EvenOdd, fill = SolidColor(Color.Black)).build()
                .also { cache[name] = it }
        }
    }

    /** Every name (tests render them all). */
    val allNames: Set<String> get() = logos.keys + outlines.keys
}
